function beta_mk_fail(string $msg, int $code = 400): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
function beta_mk_err($e): string { error_log('beta makers: ' . $e); return 'Could not save that change.'; }
if (isset($_GET['ajax_action']) && $_GET['ajax_action'] !== 'list') beta_mk_fail('Unknown action.');
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (empty($_POST) && empty($_FILES) && (int) ($_SERVER['CONTENT_LENGTH'] ?? 0) > 0) beta_mk_fail('The server rejected the request. Your images may be too large to upload at once.', 413);
    $bA = (string) ($_POST['maker_action'] ?? '');
    $bP = fn($k) => (string) ($_POST[$k] ?? '');
    $bText = function ($k, $lo, $hi, $label, $lines = false) use ($bP) {
        $v = trim($bP($k)); $n = mb_strlen($v);
        if ($n < $lo || $n > $hi) beta_mk_fail($lo ? "$label must be $lo to $hi characters." : "$label must be $hi characters or fewer.");
        if (preg_match($lines ? '/[\x00-\x09\x0B\x0C\x0E-\x1F\x7F]/u' : '/[\x00-\x1F\x7F]/u', $v)) beta_mk_fail("$label cannot contain control characters.");
    };
    $bBool = function (...$ks) use ($bP) { foreach ($ks as $k) if (isset($_POST[$k]) && $bP($k) !== '1') beta_mk_fail('Invalid on/off value.'); };
    $bInt = function ($k, $lo, $hi, $label) use ($bP) { $v = $bP($k); if (!preg_match('/^\d{1,4}$/', $v) || (int) $v < $lo || (int) $v > $hi) beta_mk_fail("$label must be a whole number from $lo to $hi."); };
    $bId = function ($k) use ($bP) { if (!preg_match('/^[1-9]\d{0,9}$/', $bP($k))) beta_mk_fail('Unknown project.'); };
    $bStatus = function () use ($bP) { if (!in_array($bP('status'), ['current', 'upcoming', 'finished'], true)) beta_mk_fail('Choose a status.'); };
    switch ($bA) {
        case 'save_settings':
            if (!in_array($bP('box_layout'), ['positioned', 'stacked-left', 'stacked-right'], true)) beta_mk_fail('Choose a layout.');
            if (!in_array($bP('preview_canvas'), ['1280x720', '1920x1080', '2560x1440'], true)) beta_mk_fail('Choose a preview size.');
            if (!in_array($bP('font_family'), ['Arial', 'Verdana', 'Georgia', 'Tahoma', 'Trebuchet MS', 'Times New Roman', 'Courier New', 'Inter'], true)) beta_mk_fail('Choose a font.');
            if (!in_array($bP('image_fit'), ['blur', 'cover', 'contain'], true)) beta_mk_fail('Choose an image display mode.');
            $bInt('carousel_seconds', 2, 60, 'Image change'); $bInt('project_rotate_seconds', 3, 120, 'Project rotate');
            foreach (['accent_color', 'text_color'] as $k) if (!preg_match('/^#[0-9A-Fa-f]{6}$/', $bP($k))) beta_mk_fail('Colours must be hex like #9146FF.');
            foreach (['featured', 'current', 'upcoming', 'finished'] as $b) foreach (['x', 'y'] as $ax) { $v = $bP("position_{$b}_$ax"); if (!preg_match('/^\d{1,3}(\.\d{1,4})?$/', $v) || (float) $v > 100) beta_mk_fail('Box positions must be 0 to 100.'); }
            $bBool('visible', 'show_title', 'show_description', 'show_link', 'show_featured', 'show_current', 'show_upcoming', 'show_finished');
            break;
        case 'create_project': $bText('title', 1, 255, 'Title'); $bStatus(); break;
        case 'update_project':
            $bId('id'); $bText('title', 1, 255, 'Title'); $bStatus(); $bText('description', 0, 2000, 'Description', true);
            $l = trim($bP('link_url'));
            if ($l !== '' && (mb_strlen($l) > 500 || !preg_match('#^https?://[^\s<>"\x00-\x1F\x7F]+$#i', $l))) beta_mk_fail('Link must start with http:// or https:// and have no spaces.');
            break;
        case 'delete_project': case 'set_current': $bId('id'); break;
        case 'upload_image':
            $bId('project_id');
            if (!isset($_FILES['imageFiles']['tmp_name']) || !is_array($_FILES['imageFiles']['tmp_name'])) beta_mk_fail('Choose at least one image.');
            if (count($_FILES['imageFiles']['tmp_name']) > 10) beta_mk_fail('Upload up to 10 images at a time.');
            break;
        case 'attach_image':
            $bId('project_id'); $bText('caption', 0, 255, 'Caption');
            if (!preg_match('/^[A-Za-z0-9._-]{1,255}\.(png|jpe?g|gif)$/i', $bP('media_file'))) beta_mk_fail('Choose an image from your media library.');
            break;
        case 'delete_image': if (!preg_match('/^[1-9]\d{0,9}$/', $bP('image_id'))) beta_mk_fail('Unknown image.'); break;
        default: beta_mk_fail('Unknown action.');
    }
    // A project or image id must exist in this channel.
    $bChk = ['update_project' => ['maker_projects', 'id'], 'delete_project' => ['maker_projects', 'id'], 'upload_image' => ['maker_projects', 'project_id'], 'attach_image' => ['maker_projects', 'project_id'], 'delete_image' => ['maker_project_images', 'image_id']][$bA] ?? null;
    if ($bChk) {
        $st = $db->prepare("SELECT 1 FROM {$bChk[0]} WHERE id = ? LIMIT 1"); $bv = (int) $bP($bChk[1]);
        $st->bind_param('i', $bv); $st->execute();
        if (!$st->get_result()->fetch_row()) { $st->close(); beta_mk_fail($bChk[0] === 'maker_projects' ? 'Unknown project.' : 'Unknown image.', 404); }
        $st->close();
    }
}

// List endpoint first so the browser can paint skeletons, then fetch project cards.
if (isset($_GET['ajax_action']) && $_GET['ajax_action'] === 'list') {
    while (ob_get_level()) { ob_end_clean(); }
    header('Content-Type: application/json');
    try {
        $projects = [];
        if ($res = $db->query("SELECT id, title, description, status, link_url, completed_at, updated_at FROM maker_projects ORDER BY FIELD(status,'current','upcoming','finished'), updated_at DESC, id DESC")) {
            while ($row = $res->fetch_assoc()) {
                $row['id'] = (int)$row['id'];
                $row['images'] = [];
                $projects[$row['id']] = $row;
            }
            $res->free();
        }

        $pinnedId = 0;
        if ($res = $db->query("SELECT current_project_id FROM maker_overlay_settings WHERE id = 1")) {
            if ($row = $res->fetch_assoc()) {
                $pinnedId = (int)($row['current_project_id'] ?? 0);
            }
            $res->free();
        }

        // Featured card = pinned current project, else most recently updated current project.
        $featuredId = 0;
        if ($pinnedId > 0 && isset($projects[$pinnedId]) && $projects[$pinnedId]['status'] === 'current') {
            $featuredId = $pinnedId;
        } else {
            $featuredStamp = '';
            foreach ($projects as $pid => $pr) {
                if ($pr['status'] !== 'current') { continue; }
                $stamp = (string)($pr['updated_at'] ?? '');
                if ($featuredId === 0 || strcmp($stamp, $featuredStamp) > 0
                    || ($stamp === $featuredStamp && $pid > $featuredId)) {
                    $featuredId = $pid;
                    $featuredStamp = $stamp;
                }
            }
        }

        if (!empty($projects)) {
            if ($res = $db->query("SELECT id, project_id, media_file, caption FROM maker_project_images ORDER BY sort_order ASC, id ASC")) {
                while ($img = $res->fetch_assoc()) {
                    $pid = (int)$img['project_id'];
                    if (isset($projects[$pid])) {
                        $img['id'] = (int)$img['id'];
                        $img['project_id'] = $pid;
                        $projects[$pid]['images'][] = $img;
                    }
                }
                $res->free();
            }
        }

        echo json_encode([
            'success' => true,
            'featured_id' => $featuredId,
            'projects' => array_values($projects),
        ]);
    } catch (mysqli_sql_exception $e) {
        http_response_code(500);
        error_log('beta makers list: ' . $e->getMessage());
        echo json_encode(['success' => false, 'error' => 'Could not load your projects.']);
    }
    exit();
}

